app.get('/api/platform-invoices/accountant-xls', async (req, res) => {
  const month = String(req.query.month || '');
  if (!/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'month=YYYY-MM required' });
  try {
    let rows = [];
    if (pool) {
      await ensurePlatInvTable();
      const q = await pool.query('SELECT * FROM platform_invoices WHERE month=$1 ORDER BY id', [month]);
      rows = q.rows;
    } else {
      rows = [..._memPlatInv.values()].filter(function (x) { return x.month === month; });
    }
    const buf = buildAccountantXls(rows);
    const name = 'Airbnb-VAT-' + month + '.xls';
    res.setHeader('Content-Type', 'application/vnd.ms-excel');
    res.setHeader('Content-Disposition', 'attachment; filename="' + name + '"');
    return res.end(buf);
  } catch (e) {
    return res.status(500).json({ error: e.message });
  }
});
