function piAirbnbRowsFromBookings(month, bks) {
  // hosthubYm === month — classifyAirbnbStay still opens a stay when Hosthub created is in-month
  const classified = estimateAirbnbInvoices(month, bks);
  const inv = [], credit = [];
  classified.stays.forEach(function (s) {
    const row = {
      code: s.code,
      aptId: s.aptId,
      aptName: s.aptName,
      guestName: s.guestName,
      hosthubId: s.hosthubId,
      created: s.created,
      createdOnChannel: s.createdOnChannel,
      stayKind: s.stayKind,
      docs: s.docs
    };
    if (s.inCreated) inv.push(Object.assign({}, row, { kind: 'invoice' }));
    if (s.inCancel) credit.push(Object.assign({}, row, { kind: 'credit_note' }));
  });
  return { inv: inv, credit: credit, missing: classified.missing, stays: classified.stays, estimate: classified.estimate };
}

